const sessions = new Map();

const toolDefs = [
  {
    name: 'begin_session',
    description: 'Begin a new isolated state session.',
    inputSchema: {
      type: 'object',
      properties: { session_id: { type: 'string' } },
      required: ['session_id'],
      additionalProperties: false
    }
  },
  {
    name: 'put_value',
    description: 'Store a string value for a key within a session.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string' },
        key: { type: 'string' },
        value: { type: 'string' }
      },
      required: ['session_id', 'key', 'value'],
      additionalProperties: false
    }
  },
  {
    name: 'get_value',
    description: 'Retrieve the string value for a key within a session.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string' },
        key: { type: 'string' }
      },
      required: ['session_id', 'key'],
      additionalProperties: false
    }
  }
];

function validateArgs(args, schema) {
  for (const k of Object.keys(args)) {
    if (!(k in schema.properties)) {
      throw new Error(`Unexpected argument: ${k}`);
    }
  }
  for (const req of schema.required) {
    if (!(req in args)) {
      throw new Error(`Missing required argument: ${req}`);
    }
  }
  for (const [k, v] of Object.entries(args)) {
    const prop = schema.properties[k];
    if (prop.type === 'string') {
      if (typeof v !== 'string') {
        throw new Error(`${k} must be a string`);
      }
      if ((k === 'session_id' || k === 'key') && v === '') {
        throw new Error(`${k} must be a non-empty string`);
      }
    }
  }
}

function ok(text) {
  return { content: [{ type: 'text', text }] };
}

export async function listTools() {
  return toolDefs;
}

export async function callTool(name, args = {}) {
  const def = toolDefs.find(t => t.name === name);
  if (!def) {
    throw new Error(`Unknown tool: ${name}`);
  }
  validateArgs(args, def.inputSchema);
  const session_id = args.session_id;
  if (name === 'begin_session') {
    sessions.set(session_id, new Map());
    return ok(`session ${session_id} started`);
  }
  if (!sessions.has(session_id)) {
    throw new Error(`Session not found: ${session_id}`);
  }
  if (name === 'put_value') {
    sessions.get(session_id).set(args.key, args.value);
    return ok(`set ${args.key}`);
  }
  if (name === 'get_value') {
    const store = sessions.get(session_id);
    if (!store.has(args.key)) {
      throw new Error(`Key not found: ${args.key}`);
    }
    return ok(store.get(args.key));
  }
}
